// Auto-generated from game.html — do not edit; run "npm run bundle"
export const gameHtml = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1, user-scalable=no\">\n<meta name=\"theme-color\" content=\"#05070F\">\n<title>EXPANDIA</title>\n<style>\n:root{\n  --void:#05070F;\n  --panel:#0B1026;\n  --panel-2:#111842;\n  --line:#1E2A63;\n  --cyan:#2BE7FF;\n  --magenta:#FF2D9B;\n  --yellow:#FFD23F;\n  --lime:#8CFF4F;\n  --text:#C9D6FF;\n  --dim:#6B7BB5;\n  --e:#FFD23F;\n  --m:#FF4A4A;\n  --c:#FF2D9B;\n  --s:#2BE7FF;\n  --safe-b:env(safe-area-inset-bottom,0px);\n  /* Nudge content clear of the front camera. Floor matches the .icobtn size (34px)\n     so it still shifts down if the device reports no inset (status bar is hidden). */\n  --safe-t:max(env(safe-area-inset-top,0px),34px);\n  /* System fonts only — no webfonts, so the app makes zero network requests */\n  --ui:system-ui,-apple-system,'Segoe UI',sans-serif;\n  --mono:ui-monospace,'SF Mono',Menlo,Consolas,monospace;\n}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%}\nbody{\n  margin:0;background:\n    radial-gradient(1200px 600px at 50% -10%, #17205C 0%, transparent 60%),\n    radial-gradient(800px 500px at 100% 100%, #2A0B36 0%, transparent 55%),\n    var(--void);\n  color:var(--text);\n  font-family:var(--ui);\n  display:flex;justify-content:center;\n  overscroll-behavior:none;\n  touch-action:manipulation;\n}\n#app{\n  width:100%;max-width:540px;min-height:100dvh;\n  display:flex;flex-direction:column;gap:8px;\n  padding:var(--safe-t) 12px calc(10px + var(--safe-b));\n}\n/* ---------- header ---------- */\nheader{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.brand{display:flex;flex-direction:column;line-height:1}\n.brand b{\n  font-size:20px;letter-spacing:.22em;font-weight:700;\n  background:linear-gradient(90deg,var(--cyan),var(--magenta) 70%,var(--yellow));\n  -webkit-background-clip:text;background-clip:text;color:transparent;\n}\n.hbtns{display:flex;gap:6px}\n.icobtn{\n  background:var(--panel);border:1px solid var(--line);color:var(--dim);\n  width:34px;height:34px;border-radius:9px;font-size:14px;cursor:pointer;\n  display:grid;place-items:center;\n}\n.icobtn:hover{border-color:var(--cyan);color:var(--cyan)}\n.icobtn:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}\n\n/* ---------- territory bar ---------- */\n.terr{display:flex;flex-direction:column;gap:4px}\n.terrbar{height:14px;border-radius:7px;overflow:hidden;display:flex;border:1px solid var(--line);background:#0A0E22}\n.terrbar i{display:block;height:100%;transition:width .35s cubic-bezier(.2,.9,.3,1)}\n.tp{background:linear-gradient(90deg,#0F8FA8,var(--cyan))}\n.tn{background:#131A3E}\n.ta{background:linear-gradient(90deg,var(--magenta),#8A0F52)}\n.terrlab{display:flex;justify-content:space-between;font-family:var(--mono);font-size:10px;color:var(--dim);letter-spacing:.1em}\n.terrlab b{color:var(--cyan);font-weight:400}\n.terrlab i{color:var(--magenta);font-style:normal}\n\n/* ---------- grid ---------- */\n.gridwrap{position:relative;flex:1;display:grid;place-items:center;min-height:0}\n#grid{\n  display:grid;gap:3px;width:100%;max-width:min(100%,58dvh);aspect-ratio:1;\n  padding:6px;border-radius:14px;\n  background:linear-gradient(180deg,#0A0F26,#070A18);\n  border:1px solid var(--line);\n  box-shadow:0 0 0 1px #000 inset, 0 18px 50px -20px #000;\n}\n.cell{\n  position:relative;border-radius:5px;border:1px solid #141C42;\n  background:#0A0E22;display:grid;place-items:center;\n  font-family:var(--mono);font-size:var(--gf,12px);color:#2B3768;\n  cursor:default;overflow:hidden;transition:transform .12s, box-shadow .2s, background .2s;\n}\n.cell .glyph{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;line-height:1.05}\n.cell .lv{font-size:calc(var(--gf,12px)*.6);opacity:.75}\n.cell.p{background:#0A2A38;border-color:#12667E;color:var(--cyan);cursor:pointer}\n.cell.p:active{transform:scale(.92)}\n.cell.a{background:#2E0A24;border-color:#7E1257;color:#FF7CC0}\n.cell.core::after{\n  content:'';position:absolute;inset:2px;border-radius:3px;\n  border:1px dashed currentColor;opacity:.5;\n  animation:pulse 1.6s ease-in-out infinite;\n}\n@keyframes pulse{0%,100%{opacity:.25}50%{opacity:.75}}\n.cell.reach{cursor:pointer;box-shadow:0 0 0 1px var(--cyan) inset}\n.cell.reach:not(.p):not(.a){background:#0C1430}\n.cell.reach::before{\n  content:'';position:absolute;inset:0;border-radius:4px;\n  background:radial-gradient(circle at 50% 50%, rgba(43,231,255,.18), transparent 70%);\n  animation:breathe 1.8s ease-in-out infinite;\n}\n@keyframes breathe{0%,100%{opacity:.35}50%{opacity:1}}\n.cell.reach:active{transform:scale(.9)}\n.cell.hit{animation:hit .34s ease-out}\n@keyframes hit{0%{transform:scale(1)}35%{transform:scale(1.28);box-shadow:0 0 22px var(--yellow)}100%{transform:scale(1)}}\n.cell.lost{animation:lost .34s ease-out}\n@keyframes lost{0%,100%{transform:translate(0)}25%{transform:translate(-3px,2px)}75%{transform:translate(3px,-2px)}}\n.cell:focus-visible{outline:2px solid var(--yellow);outline-offset:1px}\n\n/* floating combat text */\n.float{\n  position:absolute;z-index:30;pointer-events:none;\n  font-family:var(--mono);font-size:12px;font-weight:700;\n  text-shadow:0 0 10px currentColor;animation:floatup .9s ease-out forwards;\n}\n@keyframes floatup{0%{transform:translate(-50%,0);opacity:0}15%{opacity:1}100%{transform:translate(-50%,-38px);opacity:0}}\n\n/* ---------- streak ---------- */\n.streak{\n  display:flex;align-items:center;gap:8px;height:26px;\n  font-family:var(--mono);font-size:11px;letter-spacing:.08em;\n}\n.streak .pip{width:100%;height:5px;border-radius:3px;background:#101740;overflow:hidden;flex:1}\n.streak .pip i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--cyan),var(--yellow));transition:width .3s}\n.streak b{color:var(--yellow);min-width:52px;text-align:right}\n.streak .tag{color:var(--dim)}\n.streak.on b{animation:blink .5s steps(2) infinite}\n@keyframes blink{50%{opacity:.45}}\n\n/* ---------- turn timer ---------- */\n.turnring{\n  position:relative;height:4px;border-radius:2px;overflow:hidden;\n  background:#101740;border:1px solid var(--line);\n}\n.turnring i{\n  display:block;height:100%;width:100%;transform-origin:left;\n  background:linear-gradient(90deg,var(--cyan),var(--yellow));\n  transition:transform linear;\n}\n.turnring.warn i{background:linear-gradient(90deg,var(--yellow),var(--magenta))}\n.turnring.hide{opacity:0}\n\n/* ---------- resource deck ---------- */\n.deck{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}\n.rbtn{\n  position:relative;border:1px solid var(--line);background:var(--panel);\n  border-radius:11px;padding:8px 4px 7px;cursor:pointer;color:var(--text);\n  display:flex;flex-direction:column;align-items:center;gap:2px;\n  font-family:var(--ui);transition:transform .1s,border-color .2s,background .2s;\n}\n.rbtn .ic{font-size:19px;line-height:1;padding:2px 0}\n.rbtn .nm{font-size:9px;letter-spacing:.14em;color:var(--dim)}\n.rbtn[data-r=\"E\"]{--k:var(--e)} .rbtn[data-r=\"M\"]{--k:var(--m)}\n.rbtn[data-r=\"C\"]{--k:var(--c)} .rbtn[data-r=\"S\"]{--k:var(--s)}\n.rbtn.sel{border-color:var(--k);background:linear-gradient(180deg,color-mix(in srgb,var(--k) 16%,var(--panel)),var(--panel));box-shadow:0 0 16px -4px var(--k)}\n.rbtn.sel .nm{color:var(--k)}\n.rbtn:active{transform:translateY(1px)}\n.rbtn:focus-visible{outline:2px solid var(--k);outline-offset:2px}\n\n.rbtn .beats{\n  position:absolute;top:3px;right:5px;font-size:8px;font-family:var(--mono);\n  color:var(--dim);opacity:.8\n}\n\n/* ---------- overdrive ---------- */\n.od{\n  display:flex;align-items:center;gap:8px;border:1px solid var(--line);\n  background:var(--panel);border-radius:11px;padding:7px 10px;\n}\n.od .lab{font-size:10px;letter-spacing:.18em;color:var(--dim);font-family:var(--mono)}\n.od .pips{display:flex;gap:4px;flex:1}\n.od .pips u{flex:1;height:6px;border-radius:3px;background:#101740;text-decoration:none;transition:background .25s,box-shadow .25s}\n.od .pips u.on{background:var(--yellow);box-shadow:0 0 8px var(--yellow)}\n.odbtn{\n  border:1px solid var(--line);background:#0D1330;color:var(--dim);\n  border-radius:8px;padding:6px 12px;font-size:11px;letter-spacing:.14em;\n  font-family:var(--ui);font-weight:700;cursor:not-allowed;\n}\n.odbtn.ready{\n  cursor:pointer;color:#1A1300;background:var(--yellow);border-color:var(--yellow);\n  box-shadow:0 0 18px -3px var(--yellow);animation:rdy 1.2s ease-in-out infinite;\n}\n@keyframes rdy{50%{box-shadow:0 0 26px 0 var(--yellow)}}\n.odbtn:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}\n\n/* ---------- log ---------- */\n#log{\n  height:34px;overflow:hidden;border-radius:9px;border:1px solid var(--line);\n  background:#080C1E;padding:0 10px;display:flex;align-items:center;\n  font-family:var(--mono);font-size:11px;color:var(--dim);\n}\n#log b{color:var(--cyan);font-weight:400}\n#log i{color:var(--magenta);font-style:normal}\n#log u{color:var(--yellow);text-decoration:none}\n\n/* ---------- modal ---------- */\n.scrim{\n  position:fixed;inset:0;background:rgba(3,5,12,.86);backdrop-filter:blur(6px);\n  display:grid;place-items:center;padding:18px;z-index:60;\n}\n.scrim[hidden]{display:none}\n.modal{\n  width:100%;max-width:420px;background:linear-gradient(180deg,var(--panel-2),var(--panel));\n  border:1px solid var(--line);border-radius:16px;padding:18px;\n  box-shadow:0 30px 80px -20px #000;\n}\n.modal h2{\n  margin:0 0 2px;font-size:17px;letter-spacing:.2em;\n  background:linear-gradient(90deg,var(--cyan),var(--magenta));\n  -webkit-background-clip:text;background-clip:text;color:transparent;\n}\n.modal p{margin:0 0 14px;font-size:12px;color:var(--dim);line-height:1.5}\n.opt{margin-bottom:12px}\n.opt>span{display:block;font-family:var(--mono);font-size:10px;color:var(--dim);letter-spacing:.16em;margin-bottom:5px}\n.seg{display:grid;grid-auto-flow:column;gap:5px}\n.seg button{\n  border:1px solid var(--line);background:#0A1028;color:var(--dim);\n  border-radius:9px;padding:9px 4px;font-family:var(--ui);\n  font-size:11px;font-weight:600;cursor:pointer;letter-spacing:.05em;\n}\n.seg button small{display:block;font-family:var(--mono);font-size:8px;opacity:.6;margin-top:2px}\n.seg button.on{border-color:var(--cyan);color:var(--cyan);background:#0A2233;box-shadow:0 0 14px -5px var(--cyan)}\n.seg button:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}\n.play{\n  width:100%;margin-top:4px;border:none;border-radius:11px;padding:13px;\n  font-family:var(--ui);font-weight:700;font-size:14px;letter-spacing:.22em;\n  background:linear-gradient(90deg,var(--cyan),var(--magenta));color:#04070F;cursor:pointer;\n}\n.play:active{transform:translateY(1px)}\n.play:focus-visible{outline:2px solid var(--yellow);outline-offset:2px}\n.rules{font-size:11px;line-height:1.7;color:var(--dim)}\n.rules code{\n  font-family:var(--mono);color:var(--yellow);\n  background:#0B1026;padding:1px 5px;border-radius:4px;border:1px solid var(--line)\n}\n.chain{\n  display:flex;justify-content:center;align-items:center;gap:5px;flex-wrap:wrap;\n  font-family:var(--mono);font-size:11px;margin:10px 0 14px;\n}\n.chain em{font-style:normal;padding:3px 7px;border-radius:6px;border:1px solid currentColor}\n.chain .ce{color:var(--e)} .chain .cm{color:var(--m)}\n.chain .cc{color:var(--c)} .chain .cs{color:var(--s)}\n.chain span{color:var(--dim)}\n.endstat{\n  display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:12px 0 14px;\n}\n.endstat div{background:#0A1028;border:1px solid var(--line);border-radius:9px;padding:8px;text-align:center}\n.endstat b{display:block;font-family:var(--mono);font-size:17px;color:var(--yellow)}\n.endstat span{font-size:9px;color:var(--dim);letter-spacing:.1em}\n\nbody.shake #app{animation:shk .3s}\n@keyframes shk{0%,100%{transform:translate(0)}25%{transform:translate(-4px,2px)}50%{transform:translate(4px,-2px)}75%{transform:translate(-2px,-1px)}}\n\n@media (prefers-reduced-motion:reduce){\n  *{animation:none!important;transition:none!important}\n}\n@media (max-height:680px){\n  .brand b{font-size:17px}\n  #log{height:28px}\n  .rbtn{padding:6px 4px 5px}\n}\n</style>\n</head>\n<body>\n<div id=\"app\">\n  <header>\n    <div class=\"brand\"><b>EXPANDIA</b></div>\n    <div class=\"hbtns\">\n      <button class=\"icobtn\" id=\"music\" title=\"Music\">🎵</button>\n      <button class=\"icobtn\" id=\"sound\" title=\"Sound effects\">🔊</button>\n      <button class=\"icobtn\" id=\"help\" title=\"Rules\">?</button>\n      <button class=\"icobtn\" id=\"menu\" title=\"New match\">⟳</button>\n    </div>\n  </header>\n\n  <div class=\"terr\">\n    <div class=\"terrbar\"><i class=\"tp\" id=\"barP\"></i><i class=\"tn\" id=\"barN\"></i><i class=\"ta\" id=\"barA\"></i></div>\n    <div class=\"terrlab\">\n      <b id=\"labP\">YOU 1</b>\n      <span id=\"labT\">TURN 1</span>\n      <i id=\"labA\">1 AI</i>\n    </div>\n  </div>\n\n  <div class=\"gridwrap\"><div id=\"grid\"></div></div>\n\n  <div class=\"streak\" id=\"streakRow\">\n    <span class=\"tag\">STREAK</span>\n    <span class=\"pip\"><i id=\"streakFill\"></i></span>\n    <b id=\"streakTxt\">0/3</b>\n  </div>\n\n  <div class=\"deck\" id=\"deck\"></div>\n\n  <div class=\"turnring hide\" id=\"turnring\"><i id=\"turnFill\"></i></div>\n\n  <div class=\"od\">\n    <span class=\"lab\">X</span>\n    <span class=\"pips\" id=\"odPips\"></span>\n    <button class=\"odbtn\" id=\"odBtn\">OVERDRIVE</button>\n  </div>\n\n  <div id=\"log\">Pick a resource, then tap a glowing cell.</div>\n</div>\n\n<!-- setup -->\n<div class=\"scrim\" id=\"setup\">\n  <div class=\"modal\">\n    <h2>NEW MATCH</h2>\n    <p>Start from a single cell and take the grid. Your opponent is trying to do the same.</p>\n    <div class=\"opt\">\n      <span>MAP</span>\n      <div class=\"seg\" id=\"segSize\">\n        <button data-v=\"5\" class=\"on\">QUICK<small>5×5 · ~2 min</small></button>\n        <button data-v=\"8\">CLASSIC<small>8×8 · ~5 min</small></button>\n        <button data-v=\"10\">EPIC<small>10×10 · ~9 min</small></button>\n      </div>\n    </div>\n    <div class=\"opt\">\n      <span>OPPONENT</span>\n      <div class=\"seg\" id=\"segDiff\">\n        <button data-v=\"0\">EASY</button>\n        <button data-v=\"1\" class=\"on\">NORMAL</button>\n        <button data-v=\"2\">HARD</button>\n      </div>\n    </div>\n    <button class=\"play\" id=\"startBtn\">START</button>\n  </div>\n</div>\n\n<!-- help -->\n<div class=\"scrim\" id=\"helpScrim\" hidden>\n  <div class=\"modal\">\n    <h2>RULES</h2>\n    <div class=\"chain\">\n      <em class=\"cs\">🔬 S</em><span>→</span><em class=\"ce\">💰 E</em><span>→</span>\n      <em class=\"cm\">⚔️ M</em><span>→</span><em class=\"cc\">🎨 C</em><span>→</span><em class=\"cs\">🔬 S</em>\n    </div>\n    <div class=\"rules\">\n      • Pick a resource <code>E M C S</code>, then tap any cell next to your territory.<br>\n      • Empty cells are taken instantly at <b>level 1</b>. Enemy cells trigger a <b>battle</b>.<br>\n      • Attack power = level of your <b>strongest cell touching the target</b> + chain advantage (<code>+2</code>, or <code>−1</code> if the chain is against you).<br>\n      • Levels live <b>on the map</b>: tap your own cell to <b>fortify</b> it (+1 level, converts it to the selected type).<br>\n      • Captured cells always start at level 1 — power grows where you invest, not everywhere at once.<br>\n      • Successfully taking a cell charges <code>X</code> by 1 — losing a battle or fortifying doesn't.<br>\n      • Consecutive wins build a <b>streak</b>: <code>+1</code> power at 3, <code>+2</code> at 5. A loss resets it.<br>\n      • Full <code>X</code> bar (10 on Quick, 15 on Classic, 20 on Epic) = <b>OVERDRIVE</b>: instantly seize every cell directly bordering your territory, empty or enemy.<br>\n      • Fall far behind and <b>RESIST</b> kicks in: <code>+1</code> power in every battle.<br>\n      • <b>To win:</b> control the entire grid.\n    </div>\n    <button class=\"play\" id=\"helpClose\" style=\"margin-top:16px\">GOT IT</button>\n  </div>\n</div>\n\n<!-- end -->\n<div class=\"scrim\" id=\"endScrim\" hidden>\n  <div class=\"modal\">\n    <h2 id=\"endTitle\">VICTORY</h2>\n    <p id=\"endMsg\"></p>\n    <div class=\"endstat\">\n      <div><b id=\"stTurn\">0</b><span>TURNS</span></div>\n      <div><b id=\"stBest\">0</b><span>BEST STREAK</span></div>\n      <div><b id=\"stWin\">0</b><span>BATTLES WON</span></div>\n    </div>\n    <button class=\"play\" id=\"againBtn\">PLAY AGAIN</button>\n  </div>\n</div>\n\n<script>\n(()=>{\n'use strict';\n\n/* ============ constants ============ */\nconst R = ['E','M','C','S'];\nconst META = {\n  E:{ic:'💰',nm:'ECONOMY',beats:'M'},\n  M:{ic:'⚔️',nm:'MILITARY',beats:'C'},\n  C:{ic:'🎨',nm:'CULTURE', beats:'S'},\n  S:{ic:'🔬',nm:'SCIENCE', beats:'E'}\n};\nconst MAXLV = 9, WIN_SHARE = 1;\nconst MAXX_BY_SIZE = {5:10, 8:15, 10:20}; // quick, classic, epic\nfunction maxx(){ return MAXX_BY_SIZE[G.n] || 10; }\nconst TURN_MS_BY_DIFF = [4000, 3000, 2000]; // easy, normal, hard\nfunction turnMs(){ return TURN_MS_BY_DIFF[G && G.diff!=null ? G.diff : 1]; }\nconst beats = (a,b)=>META[a].beats===b;\n\n/* ============ state ============ */\nlet G = null;\nlet soundOn = true, musicOn = true;\nlet cfg = {size:5, diff:1};\nlet turnRAF = null, turnStart = 0, turnTicking = false;\n\nconst $ = s=>document.querySelector(s);\nconst gridEl = $('#grid'), deckEl = $('#deck'), logEl = $('#log');\n\n/* ============ audio engine ============ */\nlet AC=null, master=null, sfxBus=null, musBus=null, musFilter=null, noiseBuf=null;\n\nfunction audio(){\n  if(AC) return AC;\n  try{\n    AC = new (window.AudioContext||window.webkitAudioContext)();\n  }catch(e){ return null; }\n  master = AC.createGain(); master.gain.value=.85; master.connect(AC.destination);\n\n  sfxBus = AC.createGain(); sfxBus.gain.value = soundOn?1:0; sfxBus.connect(master);\n\n  musFilter = AC.createBiquadFilter();\n  musFilter.type='lowpass'; musFilter.frequency.value=1400; musFilter.Q.value=.6;\n  musBus = AC.createGain(); musBus.gain.value = musicOn?.5:0;\n  musFilter.connect(musBus); musBus.connect(master);\n\n  const n = AC.sampleRate*2;\n  noiseBuf = AC.createBuffer(1,n,AC.sampleRate);\n  const d = noiseBuf.getChannelData(0);\n  for(let i=0;i<n;i++) d[i] = Math.random()*2-1;\n  return AC;\n}\nfunction resume(){ const a=audio(); if(a && a.state==='suspended') a.resume(); return a; }\n\n/* --- primitives --- */\nfunction osc(type,f,t,dur,vol,bus,f2,detune){\n  const a=audio(); if(!a) return;\n  const o=a.createOscillator(), g=a.createGain();\n  o.type=type; o.frequency.setValueAtTime(f,t);\n  if(detune) o.detune.value=detune;\n  if(f2) o.frequency.exponentialRampToValueAtTime(Math.max(1,f2),t+dur);\n  g.gain.setValueAtTime(.0001,t);\n  g.gain.exponentialRampToValueAtTime(vol,t+.008);\n  g.gain.exponentialRampToValueAtTime(.0001,t+dur);\n  o.connect(g); g.connect(bus||sfxBus);\n  o.start(t); o.stop(t+dur+.03);\n}\nfunction noise(t,dur,vol,hp,bus){\n  const a=audio(); if(!a) return;\n  const src=a.createBufferSource(); src.buffer=noiseBuf;\n  const f=a.createBiquadFilter(); f.type='highpass'; f.frequency.value=hp||3000;\n  const g=a.createGain();\n  g.gain.setValueAtTime(vol,t);\n  g.gain.exponentialRampToValueAtTime(.0001,t+dur);\n  src.connect(f); f.connect(g); g.connect(bus||sfxBus);\n  src.start(t); src.stop(t+dur+.03);\n}\nfunction pluck(f,t,dur,vol,bus){\n  const a=audio(); if(!a) return;\n  const o=a.createOscillator(), g=a.createGain(), lp=a.createBiquadFilter();\n  o.type='square'; o.frequency.setValueAtTime(f,t);\n  lp.type='lowpass';\n  lp.frequency.setValueAtTime(f*6,t);\n  lp.frequency.exponentialRampToValueAtTime(f*1.4,t+dur);\n  g.gain.setValueAtTime(.0001,t);\n  g.gain.exponentialRampToValueAtTime(vol,t+.01);\n  g.gain.exponentialRampToValueAtTime(.0001,t+dur);\n  o.connect(lp); lp.connect(g); g.connect(bus||sfxBus);\n  o.start(t); o.stop(t+dur+.03);\n}\n\n/* --- sound effects --- */\nconst sfx = {\n  tap(){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    osc('square',900,t,.05,.10,null,1250);\n  },\n  take(){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    osc('triangle',523,t,.09,.16,null,784);\n    osc('triangle',784,t+.06,.12,.13,null,1046);\n    noise(t,.05,.06,5000);\n  },\n  win(){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    noise(t,.09,.16,1200);\n    [440,554,659].forEach((f,i)=>osc('sawtooth',f,t+i*.02,.22,.10,null,f*1.01));\n    osc('sine',160,t,.16,.22,null,60);\n  },\n  lose(){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    osc('sawtooth',220,t,.28,.14,null,70);\n    noise(t,.16,.08,700);\n  },\n  fort(){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    osc('sine',330,t,.14,.14,null,440);\n    osc('sine',440,t+.05,.16,.10);\n  },\n  streak(n){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    const notes = n>=5 ? [659,880,1046,1318,1760] : [523,659,880,1046];\n    notes.forEach((f,i)=>pluck(f,t+i*.055,.2,.14));\n    noise(t,.12,.07,6000);\n  },\n  od(){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    osc('sawtooth',110,t,.55,.16,null,880);\n    osc('square',220,t,.55,.08,null,1760);\n    noise(t,.5,.05,2000);\n    osc('sine',1318,t+.5,.3,.16,null,1760);\n  },\n  timeout(){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    osc('square',700,t,.05,.09,null,420);\n    osc('square',420,t+.07,.09,.08,null,240);\n    noise(t+.06,.08,.05,1500);\n  },\n  end(w){\n    if(!soundOn) return; const a=resume(); if(!a) return; const t=a.currentTime;\n    duck(2.2);\n    if(w){\n      [[523,0],[659,.12],[784,.24],[1046,.36],[1318,.48]].forEach(([f,dt])=>{\n        osc('sawtooth',f,t+dt,.5,.12,null,f*1.005);\n        osc('triangle',f*2,t+dt,.3,.06);\n      });\n      noise(t,.4,.08,3000);\n    }else{\n      [[330,0],[262,.18],[196,.36],[131,.54]].forEach(([f,dt])=>osc('sawtooth',f,t+dt,.6,.13,null,f*.98));\n      noise(t+.5,.5,.06,400);\n    }\n  }\n};\nfunction duck(sec){\n  if(!musBus||!AC) return;\n  const t=AC.currentTime, v=musicOn?.5:0;\n  musBus.gain.cancelScheduledValues(t);\n  musBus.gain.setValueAtTime(musBus.gain.value,t);\n  musBus.gain.linearRampToValueAtTime(v*.25,t+.08);\n  musBus.gain.linearRampToValueAtTime(v,t+sec);\n}\n\n/* ============ music (procedural synthwave loop) ============ */\nconst CHORDS = [\n  {root:110.00, arp:[440.00,523.25,659.25,880.00], pad:[220.00,261.63,329.63]}, // Am\n  {root: 87.31, arp:[349.23,440.00,523.25,698.46], pad:[174.61,220.00,261.63]}, // F\n  {root:130.81, arp:[523.25,659.25,783.99,1046.5], pad:[261.63,329.63,392.00]}, // C\n  {root: 98.00, arp:[392.00,493.88,587.33,783.99], pad:[196.00,246.94,293.66]}  // G\n];\nconst MUS = { bpm:112, step:0, next:0, timer:null, running:false, arpI:0 };\n\nfunction intensity(){\n  if(!G || G.over) return 0;\n  const tot=G.n*G.n, fill=(owned('p').length+owned('a').length)/tot;\n  let lv = fill<.3 ? 0 : fill<.65 ? 1 : 2;\n  if(G.streak.p>=3) lv = Math.min(2, lv+1);\n  return lv;\n}\nfunction playStep(k, t){\n  const a=AC; if(!a) return;\n  const bar = Math.floor(k/16) % 4;\n  const ch = CHORDS[bar];\n  const st = k % 16;\n  const iv = intensity();\n\n  // kick — four on the floor\n  if(st%4===0){\n    const o=a.createOscillator(), g=a.createGain();\n    o.type='sine'; o.frequency.setValueAtTime(140,t);\n    o.frequency.exponentialRampToValueAtTime(45,t+.12);\n    g.gain.setValueAtTime(.5,t); g.gain.exponentialRampToValueAtTime(.0001,t+.16);\n    o.connect(g); g.connect(musBus); o.start(t); o.stop(t+.2);\n  }\n  // clap\n  if(st===4||st===12) noise(t,.11,.13,1400,musBus);\n  // hi-hat\n  if(iv>=1 && st%2===1) noise(t,.03,.05,7000,musBus);\n  if(iv>=2 && st%2===0 && st%4!==0) noise(t,.02,.03,8000,musBus);\n\n  // bass\n  if([0,3,6,8,11,14].includes(st)){\n    const o=a.createOscillator(), g=a.createGain(), lp=a.createBiquadFilter();\n    o.type='sawtooth'; o.frequency.setValueAtTime(ch.root,t);\n    lp.type='lowpass'; lp.frequency.setValueAtTime(320+iv*140,t); lp.Q.value=4;\n    g.gain.setValueAtTime(.0001,t);\n    g.gain.exponentialRampToValueAtTime(.26,t+.01);\n    g.gain.exponentialRampToValueAtTime(.0001,t+.16);\n    o.connect(lp); lp.connect(g); g.connect(musBus);\n    o.start(t); o.stop(t+.2);\n  }\n  // arpeggio\n  if(iv>=1 && st%2===0){\n    const f = ch.arp[MUS.arpI % ch.arp.length]; MUS.arpI++;\n    pluck(f, t, .16, iv>=2?.075:.05, musBus);\n    if(iv>=2) pluck(f, t+.09, .1, .025, musBus);   // echo tail\n  }\n  // pad — on chord change\n  if(st===0){\n    ch.pad.forEach((f,i)=>{\n      const o=a.createOscillator(), g=a.createGain();\n      o.type='sawtooth'; o.frequency.value=f; o.detune.value=(i-1)*7;\n      const dur = (60/MUS.bpm)*4;\n      g.gain.setValueAtTime(.0001,t);\n      g.gain.linearRampToValueAtTime(.028+iv*.008,t+.35);\n      g.gain.linearRampToValueAtTime(.0001,t+dur);\n      o.connect(g); g.connect(musFilter);\n      o.start(t); o.stop(t+dur+.05);\n    });\n  }\n}\nfunction musicTick(){\n  if(!AC || !MUS.running) return;\n  const spb = (60/MUS.bpm)/4;\n  while(MUS.next < AC.currentTime + .12){\n    if(MUS.next > AC.currentTime - .05) playStep(MUS.step, MUS.next);\n    MUS.next += spb;\n    MUS.step = (MUS.step+1) % 64;\n  }\n  // filter opens up as the match heats up\n  const target = 900 + intensity()*900;\n  musFilter.frequency.setTargetAtTime(target, AC.currentTime, .8);\n}\nfunction musicStart(){\n  const a=resume(); if(!a) return;\n  if(MUS.running) return;\n  MUS.running=true; MUS.step=0; MUS.arpI=0; MUS.next=a.currentTime+.1;\n  clearInterval(MUS.timer);\n  MUS.timer=setInterval(musicTick,25);\n}\n\n/* ============ turn timer ============ */\nconst ringEl = ()=>$('#turnring'), fillEl = ()=>$('#turnFill');\nfunction turnStop(){\n  turnTicking=false;\n  if(turnRAF) cancelAnimationFrame(turnRAF);\n  ringEl().classList.add('hide');\n  ringEl().classList.remove('warn');\n}\nfunction turnStart_(){\n  if(G.over||G.busy) return;\n  turnTicking=true;\n  turnStart=performance.now();\n  ringEl().classList.remove('hide');\n  ringEl().classList.remove('warn');\n  const tick=()=>{\n    if(!turnTicking) return;\n    const el=performance.now()-turnStart, left=Math.max(0,1-el/turnMs());\n    fillEl().style.transform='scaleX('+left+')';\n    if(left<.28) ringEl().classList.add('warn');\n    if(left<=0){ turnTicking=false; onTurnTimeout(); return; }\n    turnRAF=requestAnimationFrame(tick);\n  };\n  turnRAF=requestAnimationFrame(tick);\n}\nfunction turnPoke(){ if(!G.over&&!G.busy) turnStart_(); }   // resets the clock after any player action\nfunction onTurnTimeout(){\n  if(G.over||G.busy) return;\n  turnStop();\n  sfx.timeout();\n  say('<i>Too slow — turn passed to the AI.</i>');\n  G.streak.p=0;\n  G.busy=true; render();\n  setTimeout(aiTurn,220);\n}\n\n/* ============ setup ============ */\nfunction newGame(){\n  const n = cfg.size;\n  G = {\n    n, diff:cfg.diff, turn:1, over:false, busy:false, sel:'E',\n    cells: Array.from({length:n*n},()=>({o:null,t:null,s:0,core:false})),\n    x:  {p:0,a:0},\n    streak:{p:0,a:0}, best:0, wins:0\n  };\n  const pi = idx(n-1,0), ai = idx(0,n-1);\n  Object.assign(G.cells[pi],{o:'p',t:'M',s:2,core:true});\n  Object.assign(G.cells[ai],{o:'a',t:'M',s:2,core:true});\n  buildGrid(); buildDeck(); render();\n  say('Pick a resource, then tap a glowing cell.');\n  turnStop(); turnStart_();\n}\nconst idx = (r,c)=>r*G.n+c;\nconst rc = i=>[Math.floor(i/G.n), i%G.n];\n\n// orthogonal-only (no diagonals) — a cell only \"touches\" up/down/left/right\nfunction neighbors(i){\n  const [r,c]=rc(i), out=[];\n  [[-1,0],[1,0],[0,-1],[0,1]].forEach(([dr,dc])=>{\n    const nr=r+dr, nc=c+dc;\n    if(nr>=0&&nr<G.n&&nc>=0&&nc<G.n) out.push(idx(nr,nc));\n  });\n  return out;\n}\nconst owned = w => G.cells.reduce((a,c,i)=>(c.o===w&&a.push(i),a),[]);\nfunction frontier(w){\n  const set = new Set();\n  owned(w).forEach(i=>neighbors(i).forEach(j=>{ if(G.cells[j].o!==w) set.add(j); }));\n  return [...set];\n}\n\n/* ============ DOM ============ */\nfunction buildGrid(){\n  gridEl.style.gridTemplateColumns = `repeat(${G.n},1fr)`;\n  gridEl.style.setProperty('--gf', (G.n<=5?22:G.n<=8?15:12)+'px');\n  gridEl.innerHTML='';\n  G.cells.forEach((_,i)=>{\n    const d=document.createElement('div');\n    d.className='cell'; d.dataset.i=i;\n    d.innerHTML='<span class=\"glyph\"></span>';\n    d.addEventListener('click',()=>onCell(i));\n    d.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); onCell(i); } });\n    gridEl.appendChild(d);\n  });\n}\nfunction buildDeck(){\n  deckEl.innerHTML='';\n  R.forEach(r=>{\n    const b=document.createElement('button');\n    b.className='rbtn'; b.dataset.r=r;\n    b.innerHTML=`<span class=\"beats\">▸${META[r].beats}</span>\n      <span class=\"ic\">${META[r].ic}</span>\n      <span class=\"nm\">${META[r].nm}</span>\n`;\n    b.addEventListener('click',()=>pick(r));\n    deckEl.appendChild(b);\n  });\n  $('#odPips').innerHTML = Array.from({length:maxx()},()=>'<u></u>').join('');\n}\n\nfunction render(){\n  // cells\n  const reach = G.over||G.busy ? new Set() : new Set(frontier('p'));\n  G.cells.forEach((c,i)=>{\n    const el = gridEl.children[i];\n    el.className = 'cell' + (c.o?' '+c.o:'') + (c.core?' core':'') + (reach.has(i)?' reach':'');\n    const g = el.firstElementChild;\n    g.innerHTML = c.o ? `${META[c.t].ic}<span class=\"lv\">${c.s}</span>` : '';\n    el.tabIndex = (reach.has(i)||c.o==='p') ? 0 : -1;\n  });\n  // territory bar\n  const p=owned('p').length, a=owned('a').length, tot=G.n*G.n;\n  $('#barP').style.width = (p/tot*100)+'%';\n  $('#barA').style.width = (a/tot*100)+'%';\n  $('#barN').style.width = ((tot-p-a)/tot*100)+'%';\n  $('#labP').textContent = 'YOU '+p;\n  $('#labA').textContent = a+' AI';\n  $('#labT').textContent = 'TURN '+G.turn + (resist('p')?' · RESIST':'');\n  // resource deck\n  R.forEach(r=>{\n    deckEl.querySelector(`[data-r=\"${r}\"]`).classList.toggle('sel', G.sel===r);\n  });\n  // overdrive\n  [...$('#odPips').children].forEach((u,k)=>u.classList.toggle('on',k<G.x.p));\n  const ob=$('#odBtn');\n  ob.classList.toggle('ready', G.x.p>=maxx());\n  ob.textContent = 'OVERDRIVE';\n  // streak\n  const st=G.streak.p;\n  $('#streakFill').style.width = Math.min(100, st/5*100)+'%';\n  $('#streakTxt').textContent = st>=5?'+2 PWR':st>=3?'+1 PWR':st+'/3';\n  $('#streakRow').classList.toggle('on', st>=3);\n}\n// Wrapped in a single span: #log is a flex container, and without this each text\n// node and <b>/<i> becomes its own flex item, which strips the spaces between them.\nfunction say(html){ logEl.innerHTML = '<span>'+html+'</span>'; }\n\n/* ============ power math ============ */\nconst resist = w => {\n  const me=owned(w).length, foe=owned(w==='p'?'a':'p').length;\n  return me>0 && me < foe*.6;\n};\n// strongest own cell adjacent to target = the attacking force\nfunction atkLevel(w,i){\n  let lv=1;\n  neighbors(i).forEach(j=>{ const c=G.cells[j]; if(c.o===w && c.s>lv) lv=c.s; });\n  return lv;\n}\nfunction power(w,r,defT,lv){\n  let p = lv;\n  if(beats(r,defT)) p+=2;\n  else if(beats(defT,r)) p-=1;\n  if(w==='a' && G.diff===0) return p;\n  const st=G.streak[w];\n  if(st>=5) p+=2; else if(st>=3) p+=1;\n  if(resist(w)) p+=1;\n  return p;\n}\nconst defPower = c => c.s + (c.core?2:0);\nconst chance = (atk,def,bonus=0)=>Math.max(.15, Math.min(.92, .5 + .12*(atk-def) + bonus));\n\n/* ============ moves ============ */\nfunction pick(r){\n  if(G.over||G.busy) return;\n  G.sel=r; sfx.tap(); render();\n}\nfunction onCell(i){\n  if(G.over||G.busy) return;\n  const c=G.cells[i];\n  const adj = neighbors(i).some(j=>G.cells[j].o==='p');\n  if(c.o==='p'){ doMove('p',i,'fort'); return; }\n  if(!adj){ say('You can only reach cells next to your own territory.'); return; }\n  doMove('p', i, c.o ? 'battle' : 'take');\n}\n\nfunction doMove(w,i,kind){\n  G.busy=true;\n  const c=G.cells[i];\n  const use = w==='p' ? G.sel : G.aiPick;\n  let won=true, txt='', col='var(--cyan)', fx='hit';\n\n  if(kind==='fort'){\n    c.s = Math.min(MAXLV, c.s+1); c.t = use;\n    txt='FORTIFIED L'+c.s; col='var(--lime)';\n    if(w==='p') sfx.fort();\n  } else if(kind==='take'){\n    Object.assign(c,{o:w,t:use,s:1});\n    txt='CAPTURED'; col= w==='p'?'var(--cyan)':'var(--magenta)';\n    if(w==='p') sfx.take();\n  } else {\n    const lv = atkLevel(w,i);\n    const atk = power(w,use,c.t,lv);\n    const def = defPower(c);\n    const bonus = (w==='p' && G.diff===0) ? .10 : 0;\n    won = Math.random() < chance(atk,def,bonus);\n    if(won){\n      const wasCore=c.core;\n      Object.assign(c,{o:w,t:use,s:1});\n      if(wasCore) c.core=true;\n      txt = `${atk}v${def} ✔`;\n      col = w==='p'?'var(--yellow)':'var(--magenta)';\n      if(w==='p'){ G.wins++; sfx.win(); shake(); }\n    } else {\n      txt = `${atk}v${def} ✘`; col='var(--dim)'; fx='lost';\n      if(w==='p') sfx.lose();\n    }\n  }\n\n  // streak\n  if(kind!=='fort'){\n    if(won){ G.streak[w]++; if(w==='p'&&G.streak.p>G.best) G.best=G.streak.p; }\n    else G.streak[w]=0;\n  }\n  if(w==='p'&&won&&kind!=='fort'&&(G.streak.p===3||G.streak.p===5)){\n    sfx.streak(G.streak.p);\n    popup(i, G.streak.p>=5?'STREAK +2 PWR':'STREAK +1 PWR','var(--lime)');\n  }\n\n  // X charge — only successful captures build overdrive\n  if(kind!=='fort' && won) G.x[w] = Math.min(maxx(), G.x[w]+1);\n\n  popup(i,txt,col);\n  if(w==='p'){\n    say(kind==='fort' ? 'Cell fortified to level <u>'+c.s+'</u>.'\n      : won ? 'Cell taken with <b>'+META[use].nm+'</b>.'\n            : '<i>Attack repelled.</i> Streak reset.');\n  } else {\n    say(won ? 'AI moved with <i>'+META[use].nm+'</i>.' : 'AI attack <b>repelled</b>.');\n  }\n  render();\n  flash(i,fx);\n\n  if(checkEnd()) { G.busy=false; turnStop(); return; }\n  if(w==='p') { turnStop(); setTimeout(aiTurn, 260); }\n  else { G.turn++; G.busy=false; render(); turnPoke(); }\n}\n\nfunction overdriveBlast(w){\n  G.busy=true;\n  const use = w==='p' ? G.sel : G.aiPick;\n  const targets = frontier(w);\n  let taken=0;\n  targets.forEach(i=>{\n    const c=G.cells[i];\n    const wasEnemy = !!c.o && c.o!==w;\n    const wasCore = c.core;\n    Object.assign(c,{o:w,t:use,s:1});\n    if(wasCore) c.core=true;\n    if(wasEnemy) taken++;\n    flash(i,'hit');\n  });\n  if(w==='p') G.wins += taken;\n  G.x[w]=0;\n  if(w==='p') sfx.od();\n  shake();\n  say(w==='p'\n    ? '<u>OVERDRIVE</u> — seized <b>'+targets.length+'</b> cell'+(targets.length===1?'':'s')+' at once!'\n    : 'AI unleashed <b>OVERDRIVE</b> — '+targets.length+' cells lost!');\n  render();\n\n  if(checkEnd()) { G.busy=false; turnStop(); return; }\n  if(w==='p') { turnStop(); setTimeout(aiTurn, 260); }\n  else { G.turn++; G.busy=false; render(); turnPoke(); }\n}\n\nfunction flash(i,cls){\n  const el=gridEl.children[i];\n  el.classList.remove('hit','lost'); void el.offsetWidth; el.classList.add(cls);\n}\nfunction popup(i,txt,col){\n  const el=gridEl.children[i], gr=gridEl.getBoundingClientRect(), b=el.getBoundingClientRect();\n  const s=document.createElement('div');\n  s.className='float'; s.textContent=txt; s.style.color=col;\n  s.style.left=(b.left-gr.left+b.width/2)+'px';\n  s.style.top=(b.top-gr.top-4)+'px';\n  gridEl.parentElement.appendChild(s);\n  setTimeout(()=>s.remove(),900);\n}\nfunction shake(){ document.body.classList.add('shake'); setTimeout(()=>document.body.classList.remove('shake'),300); }\n\n/* ============ AI ============ */\nfunction aiTurn(){\n  if(G.over) return;\n  const targets = frontier('a');\n  if(!targets.length){ G.turn++; G.busy=false; render(); turnPoke(); return; }\n\n  const d=G.diff;\n  let best=null;\n\n  // option A: expand / attack a frontier cell\n  targets.forEach(i=>{\n    const c=G.cells[i];\n    const openN = neighbors(i).filter(j=>!G.cells[j].o).length;\n    const lv = atkLevel('a',i);\n    R.forEach(r=>{\n      let sc = Math.random()*(d===0?11:d===1?5:.8);\n      if(!c.o){\n        // empty land = growth; cells with room to breathe are worth more\n        sc += 4 + openN*.5;\n      } else {\n        const atk=power('a',r,c.t,lv), def=defPower(c);\n        const p=chance(atk,def);\n        sc += p*8 - 3.2;\n        if(c.core) sc += d===2?8:3;\n        if(d===2 && p<.5) sc -= 5;          // hard AI doesn't gamble\n        if(d>0 && beats(r,c.t)) sc += 1.5;  // exploit the chain\n      }\n      if(!best || sc>best.sc) best={kind:'cell', i, r, sc, c};\n    });\n  });\n\n  // option B: fortify a threatened border cell (smarter AIs value defense)\n  if(d>0){\n    owned('a').forEach(i=>{\n      const c=G.cells[i];\n      const foeAdj = neighbors(i).filter(j=>G.cells[j].o==='p').length;\n      if(!foeAdj || c.s>=MAXLV) return;\n      let sc = Math.random()*(d===1?5:1.2) + foeAdj*1.1 - c.s*.8 + (c.core?3.5:0);\n      if(!best || sc>best.sc) best={kind:'fort', i, r:c.t, sc, c};\n    });\n  }\n\n  // hard AI saves overdrive for a real push\n  if(G.x.a>=maxx() && best.kind==='cell' && best.c.o==='p' &&\n     (d===2 ? best.c.core || owned('a').length<owned('p').length : d===1)){\n    G.aiPick = best.r;\n    overdriveBlast('a');\n    return;\n  }\n  G.aiPick = best.r;\n  doMove('a', best.i, best.kind==='fort' ? 'fort' : (best.c.o==='p' ? 'battle' : 'take'));\n}\n\n/* ============ end of match ============ */\nfunction checkEnd(){\n  const p=owned('p').length, a=owned('a').length, tot=G.n*G.n;\n  let win=null, why='';\n  if(p/tot>=WIN_SHARE){ win=true; why='You seized the entire grid!'; }\n  else if(a/tot>=WIN_SHARE){ win=false; why='The AI seized the entire grid.'; }\n  if(win===null) return false;\n  G.over=true;\n  turnStop();\n  $('#endTitle').textContent = win?'VICTORY':'DEFEAT';\n  $('#endMsg').textContent = why + (win?' Expandia is yours.':' Work the chain better next time.');\n  $('#stTurn').textContent=G.turn; $('#stBest').textContent=G.best; $('#stWin').textContent=G.wins;\n  setTimeout(()=>{ $('#endScrim').hidden=false; sfx.end(win); }, 480);\n  render();\n  return true;\n}\n\n/* ============ UI events ============ */\n$('#odBtn').addEventListener('click',()=>{\n  if(G.over||G.busy||G.x.p<maxx()) return;\n  overdriveBlast('p');\n});\ndocument.addEventListener('keydown',e=>{\n  const k=e.key.toUpperCase();\n  if(R.includes(k)) pick(k);\n  if(k==='X') $('#odBtn').click();\n});\n$('#sound').addEventListener('click',e=>{\n  soundOn=!soundOn;\n  e.currentTarget.textContent = soundOn?'🔊':'🔇';\n  e.currentTarget.style.color = soundOn?'':'#3A4478';\n  if(sfxBus) sfxBus.gain.setTargetAtTime(soundOn?1:0, AC.currentTime, .02);\n});\n$('#music').addEventListener('click',e=>{\n  musicOn=!musicOn;\n  e.currentTarget.textContent = musicOn?'🎵':'🔕';\n  e.currentTarget.style.color = musicOn?'':'#3A4478';\n  if(musBus) musBus.gain.setTargetAtTime(musicOn?.5:0, AC.currentTime, .05);\n  if(musicOn && !MUS.running) musicStart();\n});\n$('#help').addEventListener('click',()=>{ turnStop(); $('#helpScrim').hidden=false; });\n$('#helpClose').addEventListener('click',()=>{ $('#helpScrim').hidden=true; turnPoke(); });\n$('#menu').addEventListener('click',()=>{ turnStop(); $('#setup').hidden=false; });\n$('#againBtn').addEventListener('click',()=>{ $('#endScrim').hidden=true; $('#setup').hidden=false; });\ndocument.querySelectorAll('.seg').forEach(seg=>{\n  seg.addEventListener('click',e=>{\n    const b=e.target.closest('button'); if(!b) return;\n    seg.querySelectorAll('button').forEach(x=>x.classList.remove('on'));\n    b.classList.add('on');\n    if(seg.id==='segSize') cfg.size=+b.dataset.v; else cfg.diff=+b.dataset.v;\n  });\n});\n$('#startBtn').addEventListener('click',()=>{\n  $('#setup').hidden=true; $('#endScrim').hidden=true;\n  newGame();\n  resume(); if(musicOn) musicStart();\n});\n\nnewGame();\n$('#setup').hidden=false;\n})();\n</script>\n</body>\n</html>\n";
